// Top-level statements: no class needed for a small program.
using System.Text;

int count = 3;                    // explicit type
var name = "renewal";             // inferred as string, and stays string forever
// name = 5;                      // compile error — caught now, not in production

Console.WriteLine($"{name}: {count}");   // string interpolation

// Immutability bites here. This allocates a new string every iteration.
var slow = "";
for (var i = 0; i < 10_000; i++)
    slow += i;                    // 10,000 allocations

// StringBuilder mutates one buffer instead.
var builder = new StringBuilder();
for (var i = 0; i < 10_000; i++)
    builder.Append(i);
var fast = builder.ToString();    // one allocation at the end

Console.WriteLine(slow.Length == fast.Length);   // True — same result, very different cost

// Digit separators are legal and make large numbers readable.
const int MaxRows = 1_000_000;

// --- reference semantics: one object, two names --------------------------
var a = new List<int> { 1, 2, 3 };
var b = a;               // copies the REFERENCE, not the list
b.Add(4);
Console.WriteLine(a.Count);   // 4 — a and b are the same list

// --- value semantics: two independent values -----------------------------
int x = 1;
int y = x;               // copies the VALUE
y++;
Console.WriteLine(x);    // 1 — unaffected

// --- methods can mutate what you pass them -------------------------------
void AddOne(List<int> items) => items.Add(99);
AddOne(a);
Console.WriteLine(a.Count);   // 5 — your list was modified

// Signal intent by accepting a read-only view instead:
int Total(IReadOnlyCollection<int> items) => items.Sum();

// --- nullable reference types (<Nullable>enable</Nullable> in the .csproj) -
string definitely = "value";
string? maybe = null;

// Console.WriteLine(maybe.Length);        // warning: possible null dereference
Console.WriteLine(maybe?.Length ?? 0);     // null-conditional + null-coalescing

// --- records compare by value --------------------------------------------
record Customer(string Id, string Name);

var c1 = new Customer("C-1", "Acme");
var c2 = new Customer("C-1", "Acme");
Console.WriteLine(c1 == c2);               // True — a class would print False

// The bug that looks fine at 10 records and hangs at 10,000.
List<Order> orders = LoadOrders();       // 10,000
List<Customer> customers = LoadCustomers();  // 10,000

// O(n*m) — 100,000,000 comparisons. Appears to hang.
foreach (var order in orders)
{
    var customer = customers.First(c => c.Id == order.CustomerId);   // scans the list
    Console.WriteLine($"{customer.Name}: {order.Total}");
}

// O(n+m) — build the index once, then look up in roughly constant time.
var byId = customers.ToDictionary(c => c.Id);
foreach (var order in orders)
{
    if (byId.TryGetValue(order.CustomerId, out var customer))        // no scan
        Console.WriteLine($"{customer.Name}: {order.Total}");
}

// TryGetValue over indexing: indexing throws when the key is absent, and
// "the customer might be missing" is a real case in imported data.

// HashSet when the only question is membership.
var seen = new HashSet<string>();
foreach (var order in orders)
    if (!seen.Add(order.Reference))          // Add returns false if already present
        Console.WriteLine($"duplicate reference: {order.Reference}");

// Specific in, restrictive out.
IReadOnlyList<Order> Recent(IEnumerable<Order> source) =>
    source.Where(o => o.Date > DateTime.Today.AddDays(-30)).ToList();

var orders = LoadOrders();

// Filter, project, sort — one expression that reads as its intent.
var recentLargeOrders = orders
    .Where(o => o.Date > DateTime.Today.AddDays(-30))
    .Where(o => o.Total > 1_000m)
    .OrderByDescending(o => o.Total)
    .Select(o => new { o.Reference, o.Total })
    .ToList();                     // executes HERE, not above

// Grouping: revenue per region, largest first.
var byRegion = orders
    .GroupBy(o => o.Region)
    .Select(g => new { Region = g.Key, Revenue = g.Sum(o => o.Total), Count = g.Count() })
    .OrderByDescending(r => r.Revenue)
    .ToList();

// --- deferred execution, demonstrated ------------------------------------
var query = orders.Where(o => o.Total > 100m);   // nothing has run yet
orders.Add(new Order { Total = 500m });
Console.WriteLine(query.Count());                // includes the new order

// Enumerating twice does the work twice:
var expensive = orders.Where(o => ExpensiveCheck(o));
var count = expensive.Count();       // runs ExpensiveCheck on every order
var first = expensive.First();       // runs it again
var once = expensive.ToList();       // materialise instead, then reuse

// --- First vs FirstOrDefault ---------------------------------------------
var mustExist = orders.First(o => o.Reference == knownRef);      // throws if absent — correct if that's a bug
var mightExist = orders.FirstOrDefault(o => o.Reference == userInput);
if (mightExist is null)
    Console.WriteLine("No order with that reference.");

// Any() short-circuits; Count() > 0 does not.
if (orders.Any(o => o.Total > 10_000m))
    Console.WriteLine("Has a large order");

// --- ordinary invalid input is not exceptional ---------------------------
// Bad: exceptions as control flow for something that happens constantly.
DateTime ParseBad(string input) => DateTime.Parse(input);   // throws on user typos

// Good: absence of a value is a normal result.
bool TryParseRenewal(string input, out DateTime value) =>
    DateTime.TryParse(input, out value);

// --- catch specifically, and only what you can handle --------------------
string ReadConfigOrDefault(string path)
{
    try
    {
        return File.ReadAllText(path);
    }
    catch (FileNotFoundException)
    {
        // We CAN handle this: a missing config file means use defaults.
        return DefaultConfig;
    }
    // UnauthorizedAccessException is deliberately NOT caught. We cannot fix a
    // permissions problem here, and hiding it would produce a silently wrong
    // configuration in production.
}

// --- preserving the stack trace ------------------------------------------
void Process(Order order)
{
    try
    {
        Validate(order);
    }
    catch (ValidationException)
    {
        Log.Warning("validation failed for order {Reference}", order.Reference);
        throw;        // CORRECT: rethrows with the original stack trace
        // throw ex;  // WRONG: stack trace now starts here; you lose the origin
    }
}

// --- messages carry the values -------------------------------------------
if (!DateTime.TryParse(raw, out var renewal))
    throw new FormatException(
        $"renewal_date '{raw}' could not be parsed for customer {customerId}; expected ISO 8601");

