// --- blocking breaks it --------------------------------------------------
public RenewalReport BuildReportBad(string customerId)
{
    // Blocks the thread you were trying to free, and deadlocks in some contexts.
    return BuildReportAsync(customerId, CancellationToken.None).Result;
}

// --- independent work in parallel ----------------------------------------
public async Task<RenewalReport> BuildReportFastAsync(string customerId, CancellationToken ct)
{
    // Start both, THEN await. Neither depends on the other's result.
    Task<Customer> customerTask = _customers.GetAsync(customerId, ct);
    Task<Usage>    usageTask    = _usage.GetAsync(customerId, ct);

    await Task.WhenAll(customerTask, usageTask);

    // Sequential: 200ms + 300ms = 500ms.  Parallel: max(200, 300) = 300ms.
    return new RenewalReport(customerTask.Result, usageTask.Result);
}

// --- async void: only for event handlers ---------------------------------
public async void OnButtonClick(object sender, EventArgs e)   // acceptable here
{
    try { await DoWorkAsync(); }
    catch (Exception ex) { Log.Error(ex, "click handler failed"); }
    // The try/catch is mandatory: an escaping exception from async void
    // crashes the process rather than reaching any caller.
}

