// Data with no invariant to protect: a record, not a class.
public record TaskItem(Guid Id, string Title, TaskStatus Status, DateOnly? Due);

public enum TaskStatus { Open, InProgress, Done }

// An interface with a real reason to exist: two implementations, one of them
// used by every test.
public interface ITaskStore
{
    Task<IReadOnlyList<TaskItem>> LoadAsync(CancellationToken ct = default);
    Task SaveAsync(IReadOnlyList<TaskItem> items, CancellationToken ct = default);
}

public sealed class JsonFileTaskStore(string path) : ITaskStore
{
    public async Task<IReadOnlyList<TaskItem>> LoadAsync(CancellationToken ct = default)
    {
        if (!File.Exists(path)) return [];
        await using var stream = File.OpenRead(path);
        return await JsonSerializer.DeserializeAsync<List<TaskItem>>(stream, cancellationToken: ct) ?? [];
    }

    public async Task SaveAsync(IReadOnlyList<TaskItem> items, CancellationToken ct = default)
    {
        await using var stream = File.Create(path);
        await JsonSerializer.SerializeAsync(stream, items, cancellationToken: ct);
    }
}

// The test double. This is the second implementation that justifies the interface.
public sealed class InMemoryTaskStore : ITaskStore
{
    private List<TaskItem> _items = [];
    public Task<IReadOnlyList<TaskItem>> LoadAsync(CancellationToken ct = default)
        => Task.FromResult<IReadOnlyList<TaskItem>>(_items);
    public Task SaveAsync(IReadOnlyList<TaskItem> items, CancellationToken ct = default)
    {
        _items = [.. items];
        return Task.CompletedTask;
    }
}

// The service knows only the promise, never which implementation it has.
public sealed class TaskService(ITaskStore store)
{
    public async Task<TaskItem> AddAsync(string title, CancellationToken ct = default)
    {
        var items = (await store.LoadAsync(ct)).ToList();
        var item = new TaskItem(Guid.NewGuid(), title, TaskStatus.Open, null);
        items.Add(item);
        await store.SaveAsync(items, ct);
        return item;
    }
}

// --- a bag of fields: any state is reachable at any time -----------------
public class BadOrder
{
    public string Status { get; set; } = "";        // "Complte" compiles fine
    public List<OrderLine> Lines { get; set; } = [];// anyone can empty it
    public decimal Total { get; set; }              // can disagree with Lines
}

// --- invalid states made unrepresentable ---------------------------------
public sealed class Order
{
    private readonly List<OrderLine> _lines;

    public Order(string reference, IEnumerable<OrderLine> lines)
    {
        _lines = [.. lines];
        // An order with no lines cannot be constructed, so no later code has
        // to handle one.
        if (_lines.Count == 0)
            throw new ArgumentException("An order must have at least one line.", nameof(lines));

        Reference = !string.IsNullOrWhiteSpace(reference)
            ? reference
            : throw new ArgumentException("Reference is required.", nameof(reference));
    }

    public string Reference { get; }
    public OrderStatus Status { get; private set; } = OrderStatus.Draft;

    // Callers cannot add or remove lines behind the class's back.
    public IReadOnlyList<OrderLine> Lines => _lines;

    // Derived, never stored — so it cannot disagree with the lines.
    public decimal Total => _lines.Sum(l => l.Quantity * l.UnitPrice);

    // The only legal transitions, each enforcing its own rule.
    public void Submit()
    {
        if (Status != OrderStatus.Draft)
            throw new InvalidOperationException($"Cannot submit an order that is {Status}.");
        Status = OrderStatus.Submitted;
    }

    public void Cancel()
    {
        if (Status == OrderStatus.Shipped)
            throw new InvalidOperationException("A shipped order cannot be cancelled.");
        Status = OrderStatus.Cancelled;
    }
}

public enum OrderStatus { Draft, Submitted, Shipped, Cancelled }
public record OrderLine(string Sku, int Quantity, decimal UnitPrice);

