// --- ask, don't construct -------------------------------------------------
public sealed class TaskService(ITaskStore store, ILogger<TaskService> logger)
{
    public async Task<TaskItem> CompleteAsync(Guid id, CancellationToken ct = default)
    {
        var items = (await store.LoadAsync(ct)).ToList();
        var index = items.FindIndex(t => t.Id == id);
        if (index < 0) throw new KeyNotFoundException($"No task with id {id}.");

        items[index] = items[index] with { Status = TaskStatus.Done };
        await store.SaveAsync(items, ct);
        logger.LogInformation("Completed task {TaskId}", id);
        return items[index];
    }
}

