public class OverdueReporter
{
    public void Run()
    {
        var json = File.ReadAllText("tasks.json");                  // I/O
        var tasks = JsonSerializer.Deserialize<List<TaskItem>>(json)!;  // parsing
        var overdue = tasks.Where(t => t.Due < DateOnly.FromDateTime(DateTime.Today)
                                    && t.Status != TaskStatus.Done);    // business rule
        var html = "<ul>" + string.Join("", overdue.Select(t => $"<li>{t.Title}</li>")) + "</ul>";
        new SmtpClient().Send("me@example.com", "team@example.com", "Overdue", html);  // email
    }
    // Reasons to change: the file format, the parser, the overdue rule, the
    // report layout, the mail transport. Five, and a change to any one risks
    // the rest. Nothing here can be tested without a file and an SMTP server.
}

// --- separated, and each piece testable alone ----------------------------

// The business rule: a pure function. No file, no network, instant to test.
public static class OverdueRule
{
    public static IReadOnlyList<TaskItem> Select(IEnumerable<TaskItem> tasks, DateOnly today) =>
        tasks.Where(t => t.Due is { } due && due < today && t.Status != TaskStatus.Done)
             .ToList();
}

// Presentation: also pure.
public static class OverdueReport
{
    public static string ToHtml(IReadOnlyList<TaskItem> tasks) =>
        $"<ul>{string.Join("", tasks.Select(t => $"<li>{t.Title}</li>"))}</ul>";
}

// Orchestration: reads at ONE level. Every detail is delegated downward.
public sealed class OverdueNotifier(ITaskStore store, IEmailSender email, TimeProvider clock)
{
    public async Task RunAsync(CancellationToken ct = default)
    {
        var tasks = await store.LoadAsync(ct);
        var today = DateOnly.FromDateTime(clock.GetUtcNow().Date);
        var overdue = OverdueRule.Select(tasks, today);
        if (overdue.Count == 0) return;
        await email.SendAsync("team@example.com", "Overdue", OverdueReport.ToHtml(overdue), ct);
    }
}

using Xunit;

public class TaskServiceTests
{
    // Each test gets a fresh in-memory store: no file system, no shared state,
    // and the whole suite runs in milliseconds.
    private static TaskService NewService() => new(new InMemoryTaskStore());

    [Fact]
    public async Task AddAsync_GivenTitle_CreatesTaskInOpenStatus()
    {
        var service = NewService();

        var task = await service.AddAsync("Write tests");

        Assert.Equal("Write tests", task.Title);
        Assert.Equal(TaskStatus.Open, task.Status);   // several asserts, one behaviour
    }

    [Theory]
    [InlineData("")]
    [InlineData("   ")]
    [InlineData(null)]
    public async Task AddAsync_GivenBlankTitle_Throws(string? title)
    {
        var service = NewService();

        // Each input is reported separately, so you see WHICH one failed.
        await Assert.ThrowsAsync<ArgumentException>(() => service.AddAsync(title!));
    }

    [Fact]
    public async Task CompleteAsync_GivenUnknownId_Throws()
    {
        var service = NewService();

        // The failure path, which is the one most likely to be wrong.
        await Assert.ThrowsAsync<KeyNotFoundException>(
            () => service.CompleteAsync(Guid.NewGuid()));
    }

    [Fact]
    public async Task ListAsync_GivenNoTasks_ReturnsEmpty()
    {
        var service = NewService();

        var tasks = await service.ListAsync();

        Assert.Empty(tasks);        // the "zero" edge, not the comfortable middle
    }
}

using Microsoft.Extensions.Time.Testing;
using Xunit;

public class OverdueNotifierTests
{
    // A fake: a real, simple implementation. Tests behaviour, survives refactors.
    private sealed class FakeEmailSender : IEmailSender
    {
        public List<(string To, string Subject, string Body)> Sent = [];
        public Task SendAsync(string to, string subject, string body, CancellationToken ct = default)
        {
            Sent.Add((to, subject, body));
            return Task.CompletedTask;
        }
    }

    [Fact]
    public async Task RunAsync_GivenOverdueTask_SendsOneEmail()
    {
        // Time is injected, so "after the due date" needs no waiting.
        var clock = new FakeTimeProvider(new DateTimeOffset(2026, 9, 20, 9, 0, 0, TimeSpan.Zero));
        var store = new InMemoryTaskStore();
        await store.SaveAsync([
            new TaskItem(Guid.NewGuid(), "Overdue one", TaskStatus.Open, new DateOnly(2026, 9, 1)),
            new TaskItem(Guid.NewGuid(), "Not due yet", TaskStatus.Open, new DateOnly(2026, 12, 1)),
            new TaskItem(Guid.NewGuid(), "Already done", TaskStatus.Done, new DateOnly(2026, 9, 1)),
        ]);
        var email = new FakeEmailSender();

        await new OverdueNotifier(store, email, clock).RunAsync();

        // Sending the email IS the behaviour here, so verifying it is legitimate.
        var sent = Assert.Single(email.Sent);
        Assert.Contains("Overdue one", sent.Body);
        Assert.DoesNotContain("Not due yet", sent.Body);
        Assert.DoesNotContain("Already done", sent.Body);
    }

    [Fact]
    public async Task RunAsync_GivenNothingOverdue_SendsNoEmail()
    {
        var clock = new FakeTimeProvider(new DateTimeOffset(2026, 1, 1, 9, 0, 0, TimeSpan.Zero));
        var email = new FakeEmailSender();

        await new OverdueNotifier(new InMemoryTaskStore(), email, clock).RunAsync();

        Assert.Empty(email.Sent);       // the quiet case, which is easy to get wrong
    }
}

