// --- the handler stays thin ----------------------------------------------
[ApiController]
[Route("api/loans")]
public class LoansController(LoanService loans) : ControllerBase
{
    // [ApiController] turns a validation failure into a 400 with field details
    // automatically — there is no `if (!ModelState.IsValid)` to write.
    [HttpPost]
    public async Task<ActionResult<LoanResponse>> Borrow(
        BorrowRequest request, CancellationToken ct)
    {
        // Bind, delegate, map. No business logic here.
        var result = await loans.BorrowAsync(request.BookId, request.MemberId, ct);

        return result switch
        {
            { IsSuccess: true } => CreatedAtAction(nameof(Get), new { id = result.Loan!.Id },
                                                   LoanResponse.From(result.Loan)),
            { Reason: BorrowFailure.BookNotFound } => NotFound(),
            { Reason: BorrowFailure.AlreadyOnLoan } => Conflict(
                new ProblemDetails { Title = "Book is already on loan", Status = 409 }),
            _ => Problem()
        };
    }

    [HttpGet("{id:guid}")]
    public async Task<ActionResult<LoanResponse>> Get(Guid id, CancellationToken ct) =>
        await loans.FindAsync(id, ct) is { } loan
            ? LoanResponse.From(loan)
            : NotFound();
}

// --- request and response models: the public contract --------------------
public record BorrowRequest(
    [Required] Guid BookId,
    [Required] Guid MemberId,
    [Range(1, 30, ErrorMessage = "Loan length must be between 1 and 30 days.")]
    int Days = 14);

// Deliberately NOT the EF entity: no navigation properties, no internal fields.
public record LoanResponse(Guid Id, string BookTitle, string MemberName, DateOnly DueOn)
{
    public static LoanResponse From(Loan loan) =>
        new(loan.Id, loan.Book!.Title, loan.Member!.Name, loan.DueOn);
}

[ApiController]
[Route("api/loans")]
public class LoansController(LoanService loans, ILogger<LoansController> log) : ControllerBase
{
    [HttpPost]
    [ProducesResponseType<LoanResponse>(StatusCodes.Status201Created)]
    [ProducesResponseType<ValidationProblemDetails>(StatusCodes.Status400BadRequest)]
    [ProducesResponseType(StatusCodes.Status404NotFound)]
    [ProducesResponseType<ProblemDetails>(StatusCodes.Status409Conflict)]
    public async Task<IActionResult> Borrow(BorrowRequest request, CancellationToken ct)
    {
        // A malformed body or a Days of 99 never reaches here: [ApiController]
        // already returned 400 with the field names.
        try
        {
            var result = await loans.BorrowAsync(request.BookId, request.MemberId, request.Days, ct);

            if (result.Reason == BorrowFailure.BookNotFound)
                return NotFound();

            // 409, not 400: the request is perfectly valid, the world is not in
            // the right state. The caller can retry this later; they cannot
            // usefully retry a 400 unchanged.
            if (result.Reason == BorrowFailure.AlreadyOnLoan)
                return Conflict(new ProblemDetails
                {
                    Title  = "Book is already on loan",
                    Detail = $"Book {request.BookId} is due back on {result.DueOn:yyyy-MM-dd}.",
                    Status = StatusCodes.Status409Conflict
                });

            var response = LoanResponse.From(result.Loan!);
            return CreatedAtAction(nameof(Get), new { id = response.Id }, response);
        }
        catch (Exception ex)
        {
            // The caller gets an id, never the stack trace. "error 4f2a1c" then
            // finds the whole story in the logs.
            var correlationId = HttpContext.TraceIdentifier;
            log.LogError(ex, "borrow failed {CorrelationId}", correlationId);
            return Problem(title: "Unable to complete the loan",
                           detail: $"Reference: {correlationId}",
                           statusCode: StatusCodes.Status500InternalServerError);
        }
    }
}

public class LibraryDbContext(DbContextOptions<LibraryDbContext> options) : DbContext(options)
{
    public DbSet<Book> Books => Set<Book>();
    public DbSet<Member> Members => Set<Member>();
    public DbSet<Loan> Loans => Set<Loan>();

    protected override void OnModelCreating(ModelBuilder b)
    {
        b.Entity<Book>(e =>
        {
            e.Property(x => x.Title).HasMaxLength(300).IsRequired();
            e.Property(x => x.Isbn).HasMaxLength(17).IsRequired();
            e.HasIndex(x => x.Isbn).IsUnique();            // enforced by the database

            // Money. Without this, some providers default to a precision that
            // silently rounds, and nobody notices until an audit.
            e.Property(x => x.ReplacementCost).HasPrecision(18, 2);
        });

        b.Entity<Loan>(e =>
        {
            e.HasOne(x => x.Book).WithMany(x => x.Loans)
             .HasForeignKey(x => x.BookId)
             // Default here would be Cascade: deleting a book would delete its
             // entire loan history, which is exactly the record we need to keep.
             .OnDelete(DeleteBehavior.Restrict);

            e.HasOne(x => x.Member).WithMany(x => x.Loans)
             .HasForeignKey(x => x.MemberId)
             .OnDelete(DeleteBehavior.Restrict);

            // Only one open loan per book — the rule enforced in the database
            // as well as the service, so a race cannot bypass it.
            e.HasIndex(x => x.BookId)
             .IsUnique()
             .HasFilter("[ReturnedOn] IS NULL");
        });
    }
}

