    .ValidateOnStart();     // a misconfigured deployment fails immediately and
                            // clearly, rather than throwing a null two hours later

// --- secrets stay out of the repository ----------------------------------
// Development:
//   dotnet user-secrets init
//   dotnet user-secrets set "Library:ConnectionString" "Server=...;Password=..."
//
// Production: environment variable. The double underscore maps to the colon.
//   Library__ConnectionString=Server=...;Password=...
//
// appsettings.json holds only non-secret defaults:
// { "Library": { "DefaultLoanDays": 14 } }

// --- structured logging ---------------------------------------------------
public sealed class LoanService(LibraryDbContext db, ILogger<LoanService> log,
                                IOptions<LibraryOptions> options)
{
    public async Task<BorrowResult> BorrowAsync(Guid bookId, Guid memberId, CancellationToken ct)
    {
        // Placeholders, not interpolation: BookId and MemberId stay searchable
        // fields, so "every event for this book" is a query rather than a grep.
        log.LogInformation("Borrow requested for book {BookId} by member {MemberId}",
                           bookId, memberId);

        var onLoan = await db.Loans.AnyAsync(l => l.BookId == bookId && l.ReturnedOn == null, ct);
        if (onLoan)
        {
            // Warning: recoverable, expected occasionally, but worth seeing if
            // it starts happening constantly.
            log.LogWarning("Book {BookId} already on loan", bookId);
            return BorrowResult.Conflict();
        }

        // Never: log.LogInformation("Member {Email} {Password}", email, password);
        return BorrowResult.Success(await CreateLoanAsync(bookId, memberId, ct));
    }
}

public class LibraryApiFactory : WebApplicationFactory<Program>
{
    private SqliteConnection _connection = null!;

    protected override void ConfigureWebHost(IWebHostBuilder builder)
    {
        builder.ConfigureServices(services =>
        {
            // Swap ONLY the database. Routing, DI, middleware order, model
            // binding and serialisation all stay real — they are what we are testing.
            services.RemoveAll<DbContextOptions<LibraryDbContext>>();

            _connection = new SqliteConnection("DataSource=:memory:");
            _connection.Open();     // in-memory SQLite lives as long as the connection
            services.AddDbContext<LibraryDbContext>(o => o.UseSqlite(_connection));

            using var scope = services.BuildServiceProvider().CreateScope();
            scope.ServiceProvider.GetRequiredService<LibraryDbContext>().Database.Migrate();
        });
    }

    protected override void Dispose(bool disposing)
    {
        _connection?.Dispose();
        base.Dispose(disposing);
    }
}

public class BorrowEndpointTests(LibraryApiFactory factory) : IClassFixture<LibraryApiFactory>
{
    [Fact]
    public async Task Borrow_GivenAvailableBook_Returns201WithLocation()
    {
        var client = factory.CreateClient();
        var (bookId, memberId) = await SeedAsync(factory);

        var response = await client.PostAsJsonAsync("/api/loans",
            new { bookId, memberId, days = 14 });

        Assert.Equal(HttpStatusCode.Created, response.StatusCode);
        Assert.NotNull(response.Headers.Location);      // a unit test never sees this

        var loan = await response.Content.ReadFromJsonAsync<LoanResponse>();
        Assert.NotNull(loan);       // also proves the JSON property names match
    }

    [Fact]
    public async Task Borrow_GivenBookAlreadyOnLoan_Returns409()
    {
        var client = factory.CreateClient();
        var (bookId, memberId) = await SeedAsync(factory);
        await client.PostAsJsonAsync("/api/loans", new { bookId, memberId, days = 14 });

        var second = await client.PostAsJsonAsync("/api/loans", new { bookId, memberId, days = 14 });

        // The conflict path: more likely to be wrong than the happy path,
        // because nobody exercises it by hand.
        Assert.Equal(HttpStatusCode.Conflict, second.StatusCode);
    }

    [Fact]
    public async Task Borrow_GivenDaysOutOfRange_Returns400WithFieldName()
    {
        var client = factory.CreateClient();
        var (bookId, memberId) = await SeedAsync(factory);

        var response = await client.PostAsJsonAsync("/api/loans",
            new { bookId, memberId, days = 99 });

        Assert.Equal(HttpStatusCode.BadRequest, response.StatusCode);
        var problem = await response.Content.ReadFromJsonAsync<ValidationProblemDetails>();
        Assert.Contains("Days", problem!.Errors.Keys, StringComparer.OrdinalIgnoreCase);
    }
